<script setup lang="ts">
type DetailData = {
  id: number; name: string; external_id: string; name_ru: string; name_en: string;
  developer: string; project_type: string; construction_status: string; completion_date: string;
  description_ru: string; description_en: string; freehold: boolean; leasehold: boolean;
  maintenance_fee: string; maintenance_fee_mode: string; sinking_fund: string; sinking_fund_mode: string;
  latitude: string; longitude: string; districts: string; amenities: string; documents: string;
  gallery: string[]; gallery_count: number; available_units: number; sold_units: number;
  group_count: number; linked_count: number; payment_count: number; asset_count: number;
  is_deleted: boolean; vue_preview: boolean; remote_updated_at: string; last_seen_at: string; synced_at: string;
  back_url: string; matching_url: string; load_url: string; units_url: string;
  groups_url: string; payments_url: string; assets_url: string; card_photos_url: string;
};
defineProps<{ data: DetailData }>();
const csrfToken = document.querySelector<HTMLInputElement>('.project-detail-page > input[name="csrfmiddlewaretoken"]')?.value || '';
</script>

<template>
  <a :href="data.back_url">← Ко всем комплексам</a>
  <section class="workspace-intro"><div class="price-review-meta"><span v-if="data.project_type" class="meta-badge">{{ data.project_type }}</span><span v-if="data.is_deleted" class="meta-badge">Удалён в источнике</span></div><h2>{{ data.name }}</h2><p class="muted">{{ data.developer || 'Застройщик не указан' }} · ID AREALISTING {{ data.external_id }}</p><p v-if="data.construction_status">Строительство: {{ data.construction_status }}<template v-if="data.completion_date"> · завершение {{ data.completion_date }}</template></p><div class="asset-list-actions"><a v-if="data.matching_url && !data.is_deleted" class="primary-action" :href="data.matching_url">Подобрать карточки →</a><form v-if="data.load_url && !data.is_deleted" method="post" :action="data.load_url"><input type="hidden" name="csrfmiddlewaretoken" :value="csrfToken"><input v-if="data.vue_preview" type="hidden" name="vue" value="1"><button type="submit" class="secondary">Обновить предложения</button></form></div></section>
  <section class="work-queue"><div class="dashboard-heading"><div><h2>Данные комплекса</h2><p class="muted">Что загружено и связано с карточками Undersun.</p></div></div><div class="project-detail-metrics"><a v-if="data.units_url" :href="data.units_url"><strong>{{ data.available_units }}</strong><span>Доступных предложений</span></a><div v-else><strong>{{ data.available_units }}</strong><span>Доступных предложений</span></div><a v-if="data.units_url" :href="data.units_url"><strong>{{ data.sold_units }}</strong><span>Проданных предложений</span></a><div v-else><strong>{{ data.sold_units }}</strong><span>Проданных предложений</span></div><a v-if="data.groups_url" :href="data.groups_url"><strong>{{ data.linked_count }} / {{ data.group_count }}</strong><span>Групп с карточками</span></a><div v-else><strong>{{ data.linked_count }} / {{ data.group_count }}</strong><span>Групп с карточками</span></div><a v-if="data.payments_url" :href="data.payments_url"><strong>{{ data.payment_count }}</strong><span>Планов оплаты</span></a><div v-else><strong>{{ data.payment_count }}</strong><span>Планов оплаты</span></div><a v-if="data.assets_url" :href="data.assets_url"><strong>{{ data.asset_count }}</strong><span>Активных материалов</span></a><div v-else><strong>{{ data.asset_count }}</strong><span>Активных материалов</span></div><a v-if="data.card_photos_url" :href="data.card_photos_url"><strong>↗</strong><span>Фото в карточках</span></a></div></section>
  <section v-if="data.gallery.length" class="work-queue"><h2>Фото комплекса · {{ data.gallery_count }}</h2><div class="project-detail-gallery"><a v-for="(url, index) in data.gallery" :key="index" :href="url" target="_blank" rel="noopener noreferrer" :aria-label="`Открыть фото ${index + 1} в полном размере`"><img :src="url" alt="" loading="lazy"></a></div><p v-if="data.gallery_count > data.gallery.length" class="muted">Показаны первые {{ data.gallery.length }} фото. Остальные доступны в материалах.</p></section>
  <section class="work-queue"><h2>Сведения из AREALISTING</h2><dl class="asset-detail-facts"><div><dt>Название на русском</dt><dd>{{ data.name_ru || '—' }}</dd></div><div><dt>Название на английском</dt><dd>{{ data.name_en || '—' }}</dd></div><div><dt>Владение</dt><dd>{{ [data.freehold ? 'Freehold' : '', data.leasehold ? 'Leasehold' : ''].filter(Boolean).join(', ') || 'Не указано' }}</dd></div><div v-if="data.maintenance_fee"><dt>Плата за обслуживание</dt><dd>{{ data.maintenance_fee }} {{ data.maintenance_fee_mode }}</dd></div><div v-if="data.sinking_fund"><dt>Sinking fund</dt><dd>{{ data.sinking_fund }} {{ data.sinking_fund_mode }}</dd></div><div v-if="data.latitude && data.longitude"><dt>Координаты</dt><dd>{{ data.latitude }}, {{ data.longitude }}</dd></div><div v-if="data.remote_updated_at"><dt>Изменено в источнике</dt><dd>{{ data.remote_updated_at }}</dd></div><div v-if="data.last_seen_at"><dt>Последний раз получено</dt><dd>{{ data.last_seen_at }}</dd></div><div><dt>Сохранено в Undersun</dt><dd>{{ data.synced_at }}</dd></div></dl><div v-if="data.description_ru || data.description_en" class="project-detail-descriptions"><div v-if="data.description_ru"><h3>Описание RU</h3><p>{{ data.description_ru }}</p></div><div v-if="data.description_en"><h3>Описание EN</h3><p>{{ data.description_en }}</p></div></div><details class="project-detail-source"><summary>География, удобства и документы источника</summary><h3>География</h3><pre>{{ data.districts }}</pre><h3>Удобства</h3><pre>{{ data.amenities }}</pre><h3>Документы</h3><pre>{{ data.documents }}</pre></details></section>
</template>
